const addAdminPage = (id, title, body) => {
  document.querySelector('main').insertAdjacentHTML('beforeend', `<section class="admin-page" id="admin-${id}">${body}</section>`);
  document.querySelector('aside nav').insertAdjacentHTML('beforeend', `<button data-admin-page="${id}" onclick="adminPage('${id}',this)">⌖ <span>${title}</span></button>`);
  adminTitles[id] = title;
};

