const alerts = document.createElement('div');
alerts.className = 'alerts-popover'; alerts.id = 'alertsPopover';
alerts.innerHTML = '<h3>تنبيهات التشغيل</h3><ul id="alertsList"><li><i>!</i><span>طلب #WS-2053 بانتظار قبول المحل</span></li><li><i>!</i><span>مندوب تحت فترة الاختبار يحتاج مراجعة</span></li><li><i>●</i><span>إعلان ممول جديد جاهز للمراجعة</span></li></ul><button onclick="clearAlerts()">تحديد الكل كمقروء</button>';
document.querySelector('.admin-actions').append(alerts);
window.toggleAlerts = () => alerts.classList.toggle('show');
window.clearAlerts = () => { document.getElementById('alertsList').innerHTML = '<li class="all-read">لا توجد تنبيهات جديدة.</li>'; const badge = document.querySelector('.admin-actions b'); if (badge) badge.textContent = '0'; toast('تم تحديد التنبيهات كمقروءة'); };
const alertButton = document.querySelector('.admin-actions button'); alertButton.setAttribute('onclick', 'toggleAlerts()');
